"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["51470"],{77966(e){e.exports=JSON.parse('{"id":"FIN-726","slug":"circuit-breaker","term":"Circuit Breaker","also_known_as":[],"difficulty":"Intermediate","definition":"A circuit breaker is a rule that temporarily halts trading on a stock exchange, or in a particular security, when prices fall or rise sharply within a short time.","explanation":["Circuit breakers are designed to prevent panic selling and give investors time to absorb information and reconsider their decisions during extreme market movements.","Market-wide circuit breakers pause trading on an entire exchange if a major index falls by certain percentages in a single day. For example, under rules used in some markets, trading might pause for 15 minutes if the index falls 7%, pause again at 13% and close for the rest of the day at 20%. The exact thresholds and durations vary between exchanges.","Single-stock circuit breakers, sometimes called trading halts or volatility pauses, stop trading in an individual share if its price moves too far, too fast, often within a set band around a reference price.","Circuit breakers were widely introduced after the 1987 stock market crash and have been refined since, including after sudden \\"flash crashes\\" caused by automated trading.","Supporters argue that they calm markets and prevent disorderly trading. Critics suggest they can sometimes increase anxiety, as traders rush to sell before a halt is triggered. Either way, they are a standard feature of modern stock exchanges."],"note":"","total":1500,"prev":{"slug":"churn-rate","term":"Churn Rate"},"next":{"slug":"circular-reference","term":"Circular Reference"}}')}}]);